Set-Location -LiteralPath $PSScriptRoot
$msg = 'sms: read the A2P campaign we were approved under, instead of inferring it. GET /god/sms-trace/campaign/{org} lists the sending accounts messaging services and reads each US A2P campaign - use case, the approved message samples verbatim, message flow, opt-in and opt-out wording, and the declared has_embedded_links and has_embedded_phone flags - alongside whatever our own database holds, so an empty A2P record reads as a records gap on our side rather than a statement about the campaign. Strictly read-only: the whole router may only list and fetch, asserted by the sweep, and never returns an auth token. Motivation: five controlled sends on one number in a 33-minute window isolated 30007 to message content. One segment with a booking URL was filtered, one segment without one was delivered, and failures span one two and four segments, so length is not the variable and opt-out language neither causes nor rescues. The public booking link is the only variable tracking the outcome, and whether the campaign was registered as sending links is a fact we can read rather than guess.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
